export const CAUSE_EFFECT_ACTIVITIES = [
{n:1,type:"mcq",micro:"Sebab & akibat",q:"'Sebab' adalah hal yang membuat sesuatu terjadi; 'akibat' adalah...",options:["hal yang terjadi karena sebab itu","hal yang terjadi sebelum sebab","hal yang tidak berhubungan"],answer:0,explain:"Sebab → akibat. Sebab adalah pemicu; akibat adalah hasil atau dampaknya.",hint:"Hasil dari sebuah sebab."},
{n:2,type:"mcq",micro:"Urutan waktu",q:"Dalam hubungan sebab-akibat, sebab selalu...",options:["terjadi sesudah akibat","terjadi sebelum akibat","terjadi pada saat yang sama persis & tidak bisa dibedakan"],answer:1,explain:"Sebab mendahului akibat. Sesuatu tidak bisa disebabkan oleh kejadian yang belum terjadi.",hint:"Mana yang lebih dulu?"},
{n:3,type:"mcq",micro:"Contoh sederhana",q:"'Aku lupa membawa payung, sehingga bajuku basah kehujanan.' Sebabnya:",options:["hujan berhenti","bajuku basah","aku lupa membawa payung"],answer:2,explain:"Lupa membawa payung adalah sebab; baju basah adalah akibatnya (dengan hujan sebagai kondisi pendukung).",hint:"Apa yang memicu baju jadi basah?"},
{n:4,type:"tf",micro:"Kata penanda",q:"Benar atau Salah: Kata seperti 'karena', 'sehingga', 'akibatnya', & 'oleh sebab itu' sering menandai adanya hubungan sebab-akibat.",answer:true,explain:"Kata-kata penghubung ini membantu kita menemukan mana bagian sebab & mana bagian akibat dalam sebuah kalimat.",hint:"'Karena' menunjuk ke sebab."},
{n:5,type:"mcq",micro:"Satu sebab, satu akibat",q:"'Saklar ditekan, lampu menyala.' Ini contoh...",options:["satu sebab menghasilkan satu akibat langsung","beberapa sebab yang menghasilkan satu akibat sekaligus","rantai panjang di mana setiap akibat menjadi sebab baru"],answer:0,explain:"Menekan saklar (sebab) langsung menyalakan lampu (akibat). Hubungan yang sederhana & langsung.",hint:"Satu tindakan → satu hasil."},
{n:6,type:"mcq",micro:"Rantai sebab-akibat",q:"'Aku bangun kesiangan → ketinggalan bus → terlambat ke sekolah → melewatkan pengumuman penting.' Ini disebut...",options:["satu sebab menimbulkan beberapa akibat sekaligus pada saat yang sama","rantai sebab-akibat, di mana tiap akibat menjadi sebab kejadian berikutnya","kebetulan yang tidak berhubungan, di mana kejadian hanya terjadi berurutan"],answer:1,explain:"Dalam rantai, satu kejadian memicu kejadian berikutnya seperti barisan domino.",hint:"Seperti domino yang saling menjatuhkan."},
{n:7,type:"mcq",micro:"Satu sebab, banyak akibat",q:"Hujan deras semalaman bisa menyebabkan: jalan tergenang, pohon tumbang, DAN udara jadi sejuk. Ini contoh...",options:["rantai sebab-akibat di mana tiap akibat menjadi sebab berikutnya","kebetulan murni yang tidak ada hubungan antara hujan dan akibat itu","satu sebab yang menimbulkan beberapa akibat sekaligus"],answer:2,explain:"Satu peristiwa besar sering memancarkan beberapa dampak berbeda pada waktu yang sama.",hint:"Satu hujan, banyak dampak."},
{n:8,type:"mcq",micro:"Banyak sebab, satu akibat",q:"Sebuah tim kalah lomba karena: kurang latihan, salah satu anggota sakit, & alat rusak di tengah lomba. Ini contoh...",options:["beberapa sebab yang bersama-sama menimbulkan satu akibat","akibat tanpa sebab","satu sebab tunggal"],answer:0,explain:"Banyak hasil di dunia nyata muncul dari gabungan beberapa sebab, bukan satu.",hint:"Beberapa hal menumpuk menuju satu hasil."},
{n:9,type:"tf",micro:"Bertanya 'mengapa'",q:"Benar atau Salah: Bertanya 'mengapa ini terjadi?' adalah cara untuk mencari sebab dari sebuah kejadian.",answer:true,explain:"'Mengapa' menuntun kita mundur dari akibat menuju sebab. 'Apa akibatnya?' menuntun kita maju dari sebab menuju dampak.",hint:"'Mengapa' → mundur ke sebab."},
{n:10,type:"mcq",micro:"Sebab vs sekadar kejadian sebelumnya",q:"'Aku memakai kaus biru, lalu ban sepedaku bocor.' Memakai kaus biru...",options:["penyebab langsung ban bocor, karena kaus biru membawa kesialan","hanya terjadi sebelumnya, bukan penyebab ban bocor","penyebab tidak langsung, karena warna kaus memengaruhi cara naik sepeda"],answer:1,explain:"Terjadi lebih dulu tidak berarti menyebabkan. Ban bocor punya sebab lain (paku, tekanan, dll), bukan warna kaus.",hint:"Sebelumnya ≠ penyebab."},
{n:11,type:"open",micro:"Sebab & akibat di harimu",q:"Tuliskan satu kejadian dari hari ini, lalu sebutkan satu sebabnya & satu akibatnya.",explain:"Melihat kejadian sehari-hari sebagai rantai sebab-akibat membantu kita memahami & memperbaikinya.",hint:"Kejadian + 1 sebab + 1 akibat.",sample:"Kejadian: aku tidak sempat sarapan pagi ini. Sebab: aku menonton video terlalu lama semalam sehingga bangun kesiangan. Akibat: menjelang jam 10 perutku lapar & aku sulit berkonsentrasi saat pelajaran."},
{n:12,type:"mcq",micro:"Menemukan akibat",q:"'Karena lampu lalu lintas mati, kendaraan menumpuk di persimpangan.' Akibatnya:",options:["lampu lalu lintas menjadi menyala terang sepanjang hari","semua kendaraan berhenti & pengemudi saling bersalaman dengan ramah","kendaraan menumpuk di persimpangan"],answer:2,explain:"Lampu mati adalah sebab; kendaraan menumpuk adalah akibat yang mengikutinya.",hint:"Apa yang terjadi sebagai hasilnya?"},
{n:13,type:"tf",micro:"Akibat bisa jadi sebab",q:"Benar atau Salah: Dalam sebuah rantai, satu hal bisa sekaligus menjadi akibat dari kejadian sebelumnya & sebab bagi kejadian berikutnya.",answer:true,explain:"'Terlambat' adalah akibat dari 'bangun kesiangan' sekaligus sebab dari 'melewatkan pengumuman'. Peran itu bergantung pada posisinya di rantai.",hint:"Bisa dua peran sekaligus."},
{n:14,type:"mcq",micro:"Prediksi akibat",q:"Jika kamu meninggalkan es krim di meja pada siang hari yang panas, akibat yang bisa diprediksi:",options:["es krim akan mencair","es krim akan berubah warna jadi biru","es krim akan mengeras"],answer:0,explain:"Memahami sebab-akibat membuat kita bisa memperkirakan apa yang akan terjadi sebelum melakukannya.",hint:"Panas + es = ?"},
{n:15,type:"mcq",micro:"Menelusuri sebab",q:"Tanaman di kamar layu. Untuk menemukan sebabnya, pertanyaan yang berguna:",options:["'Siapa yang menanamnya & apa warna pot yang ia pakai?'","'Apakah ia cukup air, cahaya, & tidak terkena hama?'","'Apakah tanaman itu lebih suka musik atau suara orang bercerita?'"],answer:1,explain:"Mencari sebab berarti memeriksa faktor-faktor yang biasanya memengaruhi hasil itu.",hint:"Periksa hal-hal yang memengaruhi tanaman."},
{n:16,type:"mcq",micro:"Akar masalah",q:"'Akar sebab' (sebab paling dasar) dari sebuah masalah adalah...",options:["sebab terakhir yang terjadi tepat sebelum masalah muncul, yang paling mudah dilihat","sebab yang paling terlihat & paling banyak dibicarakan orang di sekitar masalah itu","sebab paling awal dalam rantai, yang jika diatasi bisa mencegah masalah berulang"],answer:2,explain:"Menangani gejala di permukaan sering tidak cukup; masalah kembali jika akar sebabnya tidak diperbaiki.",hint:"Sebab paling awal & mendasar."},
{n:17,type:"order",micro:"Menelusuri rantai mundur",q:"Urutkan dari AKIBAT menuju AKAR SEBAB: 'Nilai ulanganku jelek.'",items:["Nilai ulanganku jelek","Aku tidak paham materi saat ulangan","Aku tidak belajar malam sebelumnya","Aku menghabiskan malam itu bermain karena tidak membuat jadwal belajar"],answer:[0,1,2,3],explain:"Menelusuri mundur: akibat → sebab langsung → sebab sebelumnya → akar sebab.",hint:"Mulai dari akibat, terus tanya 'mengapa'."},
{n:18,type:"mcq",micro:"Sebab yang diperlukan",q:"Api butuh oksigen untuk menyala. Oksigen di sini adalah...",options:["sebab yang diperlukan — tanpa itu akibat (api) tidak mungkin terjadi","akibat dari api","sebab yang tidak penting"],answer:0,explain:"Sebab yang diperlukan (necessary) harus ada agar akibat bisa terjadi, walau ia sendiri belum tentu cukup.",hint:"Tanpa itu, akibat mustahil."},
{n:19,type:"tf",micro:"Semua punya sebab?",q:"Benar atau Salah: Ketika sesuatu yang tidak biasa terjadi, langsung menyatakan 'itu pasti kebetulan tanpa sebab apa pun' adalah cara berpikir yang teliti.",answer:false,explain:"Sebaliknya, orang yang berpikir teliti biasanya mencari sebab lebih dulu. 'Kebetulan' baru pantas disimpulkan setelah sebab-sebab yang masuk akal diperiksa.",hint:"Cari sebab dulu sebelum menyerah ke 'kebetulan'."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Memahami sebab-akibat berguna untuk...",options:["menyalahkan orang yang paling dekat dengan kejadian & menyelesaikan masalah secepat mungkin tanpa banyak berpikir","menjelaskan mengapa sesuatu terjadi, memprediksi apa yang akan terjadi, & memutuskan tindakan untuk mengubah hasil","mengumpulkan banyak fakta tentang kejadian yang sudah lewat & menyimpannya tanpa dipakai untuk apa pun"],answer:1,explain:"Penalaran sebab-akibat adalah dasar dari menjelaskan, memprediksi, & memperbaiki keadaan.",hint:"Jelaskan, prediksi, ubah hasil."},
{n:21,type:"classify",micro:"Sebab atau akibat",q:"Dalam kalimat 'Karena jalan licin, sepeda motor itu tergelincir & pengendaranya terjatuh', kelompokkan:",items:["Jalan licin","Sepeda motor tergelincir","Pengendara terjatuh","Hujan sebelumnya membuat jalan basah"],groups:["Berperan sebagai sebab","Berperan sebagai akibat"],answer:{"Berperan sebagai sebab":["Jalan licin","Hujan sebelumnya membuat jalan basah"],"Berperan sebagai akibat":["Sepeda motor tergelincir","Pengendara terjatuh"]},explain:"Hujan → jalan licin → tergelincir → terjatuh. 'Jalan licin' adalah akibat hujan sekaligus sebab tergelincir.",hint:"Susun rantainya dari awal."},
{n:22,type:"mcq",micro:"Menemukan sebab dalam kalimat",q:"'Ban sepedaku kempes karena terkena paku di jalan.' Sebabnya:",options:["aku naik sepeda","ban sepedaku kempes","terkena paku di jalan"],answer:2,explain:"Bagian setelah 'karena' menunjukkan sebab: terkena paku.",hint:"Lihat setelah kata 'karena'."},
{n:23,type:"mcq",micro:"Menemukan akibat dalam kalimat",q:"'Ia berlatih setiap hari, sehingga permainannya makin lancar.' Akibatnya:",options:["permainannya makin lancar","ia punya alat musik","ia berlatih setiap hari"],answer:0,explain:"Bagian setelah 'sehingga' menunjukkan akibat: permainan makin lancar.",hint:"Lihat setelah kata 'sehingga'."},
{n:24,type:"mcq",micro:"Sebab tersembunyi",q:"'Kelas jadi gaduh saat guru keluar sebentar.' Sebab yang paling masuk akal:",options:["kursi-kursi kelas berwarna cokelat","tidak ada orang dewasa yang mengawasi sehingga sebagian murid mulai mengobrol","lampu kelas menyala"],answer:1,explain:"Sebab sering tidak disebut langsung; kita menyimpulkannya dari situasi (pengawasan hilang).",hint:"Apa yang berubah saat guru keluar?"},
{n:25,type:"tf",micro:"Berdekatan waktu",q:"Benar atau Salah: Dua kejadian yang terjadi berdekatan waktu pasti punya hubungan sebab-akibat.",answer:false,explain:"Sebaliknya, banyak kejadian terjadi berdekatan hanya karena kebetulan. Kedekatan waktu adalah petunjuk lemah, bukan bukti.",hint:"Berdekatan ≠ berhubungan."},
{n:26,type:"mcq",micro:"Membaca adegan",q:"Gambar: gelas pecah di lantai, kucing berdiri di meja dekat tempat gelas tadi, & tirai bergoyang. Sebab yang paling mungkin:",options:["gelas itu memang selalu pecah","lantai yang membuat gelas jatuh","kucing menyenggol gelas hingga jatuh"],answer:2,explain:"Kucing di meja dekat lokasi gelas adalah petunjuk sebab paling masuk akal, walau angin dari tirai juga mungkin.",hint:"Siapa/apa yang paling dekat & bisa menyenggol?"},
{n:27,type:"mcq",micro:"Sebab langsung vs jauh",q:"'Kue gosong karena aku lupa memasang pengatur waktu.' Sebab langsungnya: kue terlalu lama di oven. Sebab yang lebih jauh:",options:["aku lupa memasang pengatur waktu","kue itu manis","oven itu berwarna hitam"],answer:0,explain:"Sebab langsung (terlalu lama di oven) sendiri punya sebab di belakangnya (lupa pasang timer). Rantai bisa ditelusuri lebih jauh.",hint:"Apa yang menyebabkan kue terlalu lama di oven?"},
{n:28,type:"open",micro:"Susun rantai",q:"Buat rantai sebab-akibat dengan minimal 3 mata rantai yang berujung pada 'aku begadang semalam'.",explain:"Menyusun rantai membantu menemukan titik paling awal yang bisa diubah agar hasil akhirnya berbeda.",hint:"Mulai dari yang paling awal, sambungkan sampai ke hasil.",sample:"Aku menunda mengerjakan tugas sepanjang sore → menjelang malam tugasnya menumpuk & waktu tinggal sedikit → aku terpaksa mengerjakan semuanya sampai larut → aku begadang semalam. Akar sebabnya adalah menunda-nunda di sore hari."},
{n:29,type:"mcq",micro:"Kondisi vs pemicu",q:"Kebakaran kecil terjadi karena ada percikan api dekat kain kering. Kain kering adalah...",options:["pemicu utama","kondisi yang membuat kebakaran mungkin; percikan api adalah pemicunya","akibat kebakaran"],answer:1,explain:"Kondisi (kain kering) menciptakan kemungkinan; pemicu (percikan) memulai kejadian. Keduanya berperan.",hint:"Yang membuat 'mungkin' vs yang 'memulai'."},
{n:30,type:"order",micro:"Efek domino",q:"Urutkan efek domino ini dari sebab pertama:",items:["Keran di kamar mandi tidak ditutup rapat","Air meluap membasahi lantai","Buku yang ditaruh di lantai ikut basah","Tugas di dalam buku itu jadi sulit dibaca"],answer:[0,1,2,3],explain:"Tiap kejadian menjadi sebab kejadian berikutnya.",hint:"Keran dulu, tugas rusak terakhir."},
{n:31,type:"mcq",micro:"Memisahkan sebab & korban",q:"'Adik menangis setelah kakak mengambil mainannya.' Sebab tangisan:",options:["mainan itu berwarna merah","adik menangis","kakak mengambil mainan adik"],answer:2,explain:"Tindakan kakak (mengambil mainan) adalah sebab; tangisan adik adalah akibat.",hint:"Apa yang terjadi tepat sebelum tangisan?"},
{n:32,type:"tf",micro:"Prediksi berbasis sebab",q:"Benar atau Salah: Memahami sebab sebuah masalah tidak ada gunanya untuk memperkirakan kapan masalah itu akan muncul lagi.",answer:false,explain:"Sebaliknya, mengetahui sebab justru memungkinkan prediksi: bila sebabnya hadir lagi, akibatnya kemungkinan muncul lagi.",hint:"Tahu sebab → bisa memperkirakan."},
{n:33,type:"mcq",micro:"Sebab dalam cerita",q:"Dalam cerita, tokoh menjadi penakut setelah pernah tersesat di hutan waktu kecil. Hubungan ini adalah...",options:["sebab (pengalaman tersesat) & akibat (jadi penakut) pada watak tokoh","sebab (watak penakutnya) & akibat (pernah tersesat di hutan) pada tokoh itu","dua kejadian yang tidak berhubungan karena penakut adalah sifat bawaan sejak lahir"],answer:0,explain:"Penulis sering menjelaskan watak atau tindakan tokoh lewat sebab dari masa lalunya.",hint:"Pengalaman lampau membentuk sifat sekarang."},
{n:34,type:"mcq",micro:"Sebab yang keliru diduga",q:"'Setiap kali aku mencuci mobil, besoknya hujan. Jadi mencuci mobil menyebabkan hujan.' Kesalahannya:",options:["tidak ada kesalahan","dua hal terjadi berurutan beberapa kali tidak membuktikan yang satu menyebabkan yang lain; hujan punya sebab cuaca sendiri","hujan menyebabkan mencuci mobil"],answer:1,explain:"Ini kesimpulan sebab-akibat yang keliru dari urutan kejadian. Mencuci mobil tidak memengaruhi awan.",hint:"Berurutan ≠ menyebabkan."},
{n:35,type:"mcq",micro:"Menguji dugaan sebab",q:"Kamu menduga 'lampu meja mati karena kabelnya longgar'. Cara sederhana mengujinya:",options:["mengganti seluruh lampu tanpa memeriksa apa pun","mengecat ulang meja","membetulkan kabel & melihat apakah lampu menyala; bila ya, dugaan menguat"],answer:2,explain:"Menguji sebab berarti mengubah satu hal (kabel) & melihat apakah akibatnya berubah.",hint:"Ubah satu hal, amati hasilnya."},
{n:36,type:"open",micro:"Sebab & akibat dari sebuah pilihan",q:"Pikirkan satu kebiasaan baik yang ingin kamu mulai. Tuliskan kebiasaan itu & dua akibat baik yang mungkin ditimbulkannya.",explain:"Memikirkan akibat dari sebuah pilihan sebelum melakukannya membantu kita memilih dengan lebih baik.",hint:"Kebiasaan + 2 akibat baik.",sample:"Kebiasaan: menyiapkan tas & baju sekolah setiap malam sebelum tidur. Akibat baik: (1) pagi hari jadi lebih tenang & aku tidak panik mencari barang, (2) aku lebih jarang lupa membawa buku atau alat yang dibutuhkan hari itu."},
{n:37,type:"mcq",micro:"Sebab tunggal yang menyesatkan",q:"'Tim itu menang hanya karena wasitnya berpihak.' Kelemahan penjelasan sebab tunggal ini:",options:["mengabaikan sebab-sebab lain yang mungkin (latihan, strategi, kondisi pemain) demi satu penjelasan yang nyaman","mengabaikan fakta bahwa wasit memang selalu berpihak, sehingga sebab tunggal itu terlalu lemah untuk dipercaya","tidak menyebut siapa wasitnya, sehingga penjelasan itu tidak bisa dibantah oleh siapa pun yang menonton"],answer:0,explain:"Hasil yang rumit jarang punya satu sebab. Menempel pada satu sebab tunggal sering menyembunyikan gambaran yang sebenarnya.",hint:"Apakah benar-benar hanya satu sebab?"},
{n:38,type:"tf",micro:"Sebab bisa lebih dari satu",q:"Benar atau Salah: Hampir setiap akibat di dunia nyata berasal dari tepat satu sebab tunggal.",answer:false,explain:"Sebaliknya, banyak peristiwa nyata (kecelakaan, kegagalan proyek, keberhasilan) muncul dari kombinasi beberapa sebab yang bekerja bersama.",hint:"Sering banyak faktor sekaligus."},
{n:39,type:"mcq",micro:"Arah sebab-akibat",q:"'Anak yang banyak membaca punya kosakata luas.' Arah sebab-akibat yang mungkin:",options:["hanya satu arah: membaca menambah kosakata, & kosakata yang luas tidak pernah memengaruhi seberapa sering seseorang membaca","bisa dua arah: membaca menambah kosakata, & kosakata yang luas membuat membaca lebih menyenangkan sehingga makin banyak membaca","hanya satu arah: kosakata luas membuat orang membaca, & membaca tidak pernah menambah kosakata siapa pun sama sekali"],answer:1,explain:"Kadang dua hal saling menyebabkan (lingkaran). Menganggap hanya satu arah bisa menyederhanakan berlebihan.",hint:"Mungkinkah keduanya saling memengaruhi?"},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Saat menjelaskan mengapa sesuatu terjadi, kebiasaan yang baik:",options:["pilih satu sebab yang paling mudah dibayangkan & anggap hal yang terjadi sebelumnya otomatis menjadi penyebabnya","kumpulkan sebab sebanyak mungkin tetapi jangan membedakan sebab yang benar dengan kejadian yang kebetulan lebih dulu","cari beberapa kemungkinan sebab, telusuri rantainya, & bedakan 'terjadi sebelumnya' dari 'benar-benar menyebabkan'"],answer:2,explain:"Penjelasan sebab-akibat yang baik mempertimbangkan banyak faktor & menguji apakah hubungannya nyata.",hint:"Banyak kemungkinan, telusuri, uji."},
{n:41,type:"mcq",micro:"Terapan: tanaman mati",q:"Tanaman di jendela mati. Kamu ingat: tanah selalu basah becek & pot tidak punya lubang air. Sebab yang paling masuk akal:",options:["akar membusuk karena kelebihan air yang tidak bisa keluar","kurang cahaya","kekurangan air"],answer:0,explain:"Tanah becek terus + pot tanpa lubang → air menggenang → akar busuk. Petunjuk mengarah ke kelebihan air, bukan kekurangan.",hint:"Cocokkan sebab dengan petunjuk 'selalu becek'."},
{n:42,type:"mcq",micro:"Terapan: rantai terlambat",q:"Kamu terlambat ke sekolah. Menelusuri mundur: ketinggalan angkot → keluar rumah telat → sarapan lama → bangun kesiangan → alarm tidak berbunyi karena lupa diisi daya. Akar sebabnya:",options:["ketinggalan angkot","lupa mengisi daya ponsel sehingga alarm mati","sarapan"],answer:1,explain:"Akar sebab adalah titik paling awal di rantai yang, jika diperbaiki, mencegah seluruh rangkaian.",hint:"Titik paling awal di rantai."},
{n:43,type:"mcq",micro:"Terapan: memutus rantai",q:"Dari rantai di soal sebelumnya, tindakan pencegahan yang paling efektif:",options:["tidak sarapan","berlari lebih cepat ke angkot besok","memastikan ponsel terisi daya atau memakai jam alarm terpisah setiap malam"],answer:2,explain:"Mengatasi akar sebab (alarm bisa diandalkan) mencegah seluruh rantai terulang, bukan sekadar menambal akibat di ujung.",hint:"Perbaiki mata rantai paling awal."},
{n:44,type:"open",micro:"Terapan: proyek kelompok gagal",q:"Sebuah proyek kelompok tidak selesai tepat waktu. Tuliskan tiga kemungkinan sebab yang berbeda & satu cara mencegahnya lain kali.",explain:"Kegagalan biasanya punya beberapa sebab. Mengenalinya memungkinkan pencegahan yang tepat, bukan sekadar menyalahkan satu orang.",hint:"3 sebab berbeda + 1 pencegahan.",sample:"Kemungkinan sebab: (1) tugas tidak dibagi jelas sehingga beberapa bagian tidak ada yang mengerjakan, (2) tidak ada tenggat kecil, semua menunda sampai akhir, (3) anggota jarang berkomunikasi sehingga masalah baru ketahuan di hari terakhir. Cara mencegah: di awal, buat daftar tugas dengan nama penanggung jawab & tenggat bertahap, serta sepakati waktu rutin untuk saling mengabari kemajuan."},
{n:45,type:"mcq",micro:"Terapan: memprediksi akibat",q:"Sebelum kelas memutuskan menaruh kotak sumbangan buku tanpa penjaga di lorong, memikirkan akibat yang mungkin membantu. Akibat yang perlu diantisipasi:",options:["baik (buku terkumpul) & buruk (buku bisa hilang atau rusak kena hujan bila dekat jendela)","hanya baik, karena semua orang pasti menaruh buku dengan jujur & mengembalikannya tepat waktu","hanya buruk, karena kotak terbuka pasti diambil semua orang & buku tidak akan pernah terkumpul"],answer:0,explain:"Memikirkan akibat baik & buruk sebelum bertindak membantu menyiapkan pengaman (mis. kotak tertutup, dicek berkala).",hint:"Pikirkan dampak baik & buruknya."},
{n:46,type:"order",micro:"Terapan: menemukan sebab lampu padam",q:"Lampu satu ruangan padam. Urutkan langkah mencari sebabnya:",items:["Periksa apakah lampu/ruangan lain juga padam","Jika hanya ruangan ini: periksa sakelar & apakah lampu lain di ruangan itu menyala","Periksa bohlam: apakah menghitam atau kendur","Simpulkan sebab paling mungkin & perbaiki, lalu uji apakah lampu menyala"],answer:[0,1,2,3],explain:"Persempit dari umum ke khusus: seluruh gedung → satu ruangan → satu lampu → bohlam.",hint:"Dari yang paling luas ke paling sempit."},
{n:47,type:"mcq",micro:"Terapan: sebab perilaku",q:"Seorang teman tiba-tiba jadi pendiam seminggu ini. Cara berpikir sebab-akibat yang berhati-hati:",options:["menyimpulkan ia sombong","memikirkan beberapa kemungkinan sebab (masalah di rumah, sedang tidak enak badan, ada konflik) & bertanya baik-baik, bukan menebak satu & bertindak","mengabaikannya"],answer:1,explain:"Perubahan perilaku bisa punya banyak sebab. Menebak satu lalu bertindak berisiko keliru & menyakiti.",hint:"Banyak kemungkinan → tanyakan, jangan tebak satu."},
{n:48,type:"tf",micro:"Terapan: solusi sesuai sebab",q:"Benar atau Salah: Solusi yang baik untuk sebuah masalah harus menyasar sebabnya, bukan hanya menutupi akibatnya.",answer:true,explain:"Menutupi akibat (mis. mengeringkan lantai) tanpa menutup keran yang bocor membuat masalah kembali terus.",hint:"Perbaiki sebab, bukan hanya seka akibat."},
{n:49,type:"mcq",micro:"Terapan: mengubah satu variabel",q:"Kamu ingin tahu apakah pupuk membuat tanaman tumbuh lebih cepat. Percobaan yang paling adil:",options:["tanam dua kelompok di tempat yang berbeda (satu terang, satu gelap), lalu beri pupuk pada keduanya & lihat hasilnya","tanam satu kelompok saja dengan pupuk berlebih, lalu bandingkan tinggi tanaman dengan tanaman di taman tetangga","tanam dua kelompok yang diperlakukan sama (air, cahaya, tanah), hanya satu kelompok diberi pupuk, lalu bandingkan"],answer:2,explain:"Untuk menguji sebab, ubah hanya satu hal & jaga yang lain tetap sama, agar perbedaan hasil bisa dikaitkan ke hal itu.",hint:"Hanya satu perbedaan antar kelompok."},
{n:50,type:"mcq",micro:"Terapan: sebab bersama",q:"Di sekolah, jumlah anak yang membawa payung & jumlah anak yang memakai jas hujan sama-sama naik pada hari yang sama. Payung TIDAK menyebabkan jas hujan. Yang sebenarnya terjadi:",options:["ada sebab bersama: hari itu hujan, sehingga keduanya naik","jas hujan menyebabkan payung","kebetulan murni"],answer:0,explain:"Dua hal bisa naik-turun bersama karena satu sebab yang sama (hujan), bukan karena saling menyebabkan.",hint:"Apa yang membuat KEDUANYA naik?"},
{n:51,type:"mcq",micro:"Terapan: rantai kebiasaan",q:"'Aku tidur larut → mengantuk di kelas → sulit fokus → tidak paham pelajaran → harus belajar ekstra malam hari → tidur larut lagi.' Ini adalah...",options:["rantai lurus biasa","lingkaran sebab-akibat yang memberi umpan balik pada dirinya sendiri (makin lama makin parah)","kejadian tanpa sebab"],answer:1,explain:"Lingkaran seperti ini menguatkan diri sendiri. Memutusnya di satu titik (mis. menetapkan jam tidur) bisa menghentikan seluruh putaran.",hint:"Ujungnya kembali ke awal."},
{n:52,type:"open",micro:"Terapan: memutus lingkaran",q:"Untuk lingkaran 'tidur larut → mengantuk → sulit fokus → belajar ekstra → tidur larut', pilih satu titik untuk memutusnya & jelaskan bagaimana.",explain:"Pada lingkaran sebab-akibat, satu perubahan yang tepat sasaran bisa membalik seluruh putaran ke arah yang lebih baik.",hint:"Pilih 1 titik + cara nyata memutusnya.",sample:"Aku akan memutus di titik 'tidur larut'. Caranya: menetapkan jam tidur tetap pukul 21.30 & berhenti memakai layar 30 menit sebelumnya. Dengan tidur cukup, aku tidak mengantuk di kelas, lebih mudah fokus & paham, sehingga tidak perlu belajar ekstra sampai larut — & lingkaran itu melemah."},
{n:53,type:"mcq",micro:"Terapan: banyak akibat dari satu aturan",q:"Sekolah membuat aturan 'ponsel dikumpulkan saat jam pelajaran'. Akibat yang mungkin (baik & buruk):",options:["tidak ada akibatnya","hanya akibat baik","baik: murid lebih fokus, lebih sedikit gangguan; perlu diantisipasi: murid sulit dihubungi orang tua saat darurat, jadi perlu prosedur khusus"],answer:2,explain:"Satu kebijakan memancarkan beberapa akibat. Kebijakan yang baik menyiapkan cara menangani akibat buruknya.",hint:"Daftar dampak positif & negatifnya."},
{n:54,type:"tf",micro:"Terapan: menyalahkan terburu-buru",q:"Benar atau Salah: Saat sesuatu yang buruk terjadi, langkah pertama yang paling berguna adalah segera menentukan siapa yang bersalah.",answer:false,explain:"Sebaliknya, langkah pertama yang berguna adalah memahami rantai sebabnya. Fokus terlalu cepat pada 'siapa yang salah' sering menutupi sebab sistem yang sebenarnya perlu diperbaiki.",hint:"Pahami sebab dulu, bukan cari kambing hitam."},
{n:55,type:"mcq",micro:"Terapan: sebab vs alasan",q:"'Ban bocor karena tertusuk paku' vs 'Aku terlambat karena macet.' Keduanya menjelaskan sebab, tapi yang kedua juga bisa jadi...",options:["alasan/pembenaran — perlu dicek apakah macet benar-benar menyebabkan terlambat atau hanya sebagian, & apakah bisa diantisipasi","selalu bohong","bukan penjelasan sama sekali"],answer:0,explain:"Kadang 'karena' dipakai sebagai pembenaran. Berpikir kritis memeriksa apakah sebab itu benar & seberapa besar pengaruhnya.",hint:"Sebab nyata atau sekadar pembenaran?"},
{n:56,type:"order",micro:"Terapan: analisis kejadian",q:"Buku perpustakaan sering kembali terlambat bulan ini. Urutkan langkah menganalisis sebabnya:",items:["Kumpulkan data: kelas mana, buku jenis apa, terlambat berapa hari","Daftar kemungkinan sebab (jadwal berubah, denda dihapus, pengingat tidak jalan)","Cari petunjuk yang membedakan tiap sebab","Uji perbaikan pada sebab yang paling didukung & lihat apakah keterlambatan berkurang"],answer:[0,1,2,3],explain:"Data → daftar sebab → petunjuk pembeda → uji perbaikan.",hint:"Mulai dari mengumpulkan data."},
{n:57,type:"mcq",micro:"Terapan: memperkirakan efek samping",q:"Kelas ingin memajukan jam mulai piket agar kelas bersih lebih pagi. Efek samping yang perlu dipikirkan:",options:["tidak ada","petugas piket harus datang lebih awal, yang mungkin sulit bagi yang rumahnya jauh — perlu solusi seperti rotasi atau berbagi tugas","kelas akan jadi kotor"],answer:1,explain:"Setiap perubahan menimbulkan akibat lanjutan. Memikirkannya lebih dulu mencegah masalah baru.",hint:"Siapa yang terdampak oleh perubahan ini?"},
{n:58,type:"mcq",micro:"Terapan: bukti sebab yang kuat",q:"Dugaan: 'kipas angin kelas berisik karena bautnya kendur'. Bukti yang paling menguatkan:",options:["kelas sebelah kipasnya juga berisik","kipas itu sudah tua","setelah baut dikencangkan, suara berisiknya hilang; & saat baut dikendurkan lagi, berisik kembali"],answer:2,explain:"Sebab menguat bila mengubahnya mengubah akibat, & mengembalikannya mengembalikan akibat.",hint:"Ubah → akibat berubah; kembalikan → akibat kembali."},
{n:59,type:"tf",micro:"Terapan: satu kali cukup?",q:"Benar atau Salah: Kalau memperbaiki satu hal membuat masalah hilang satu kali, itu sudah membuktikan dengan pasti bahwa hal itu satu-satunya sebab.",answer:false,explain:"Sebaliknya, satu keberhasilan bisa kebetulan. Meyakinkan bila perbaikan itu berhasil berulang & masalah kembali saat perbaikan dicabut.",hint:"Sekali berhasil bisa kebetulan."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Saat menghadapi masalah nyata, penalaran sebab-akibat membantumu...",options:["menemukan akar sebab, memilih solusi yang menyasar sebab itu, & memperkirakan efek samping perubahan","menunjuk orang yang paling mungkin bersalah, memilih solusi tercepat, & berharap tidak ada efek samping","mencatat semua kejadian di sekitar masalah tanpa memilih mana yang penting & menunggu sampai masalahnya hilang sendiri"],answer:0,explain:"Menelusuri rantai, menguji dugaan, & mengantisipasi dampak lanjutan adalah cara memakai sebab-akibat untuk memperbaiki keadaan.",hint:"Akar sebab → solusi tepat → antisipasi dampak."},
{n:61,type:"mcq",micro:"Hubungan bukan sebab",q:"Ditemukan: bulan-bulan dengan penjualan es krim tinggi juga bulan dengan kasus tenggelam lebih banyak. Kesimpulan yang benar:",options:["es krim menyebabkan tenggelam, karena orang yang baru makan es krim berenang dengan perut dingin","keduanya kemungkinan disebabkan cuaca panas (lebih banyak beli es krim & lebih banyak berenang), bukan saling menyebabkan","tenggelam menyebabkan orang membeli es krim, karena mereka mencari hiburan setelah melihat kejadian itu"],answer:1,explain:"Ini contoh klasik sebab bersama (cuaca panas). Dua hal yang naik bersama belum tentu satu menyebabkan yang lain.",hint:"Cari faktor ketiga yang memengaruhi keduanya."},
{n:62,type:"mcq",micro:"Setelah itu, karena itu",q:"'Aku minum obat, lalu demamku turun keesokan harinya, jadi obat itu pasti manjur.' Kelemahan berpikirnya:",options:["obat itu tidak nyata","tidak ada kelemahan","demam sering turun sendiri seiring waktu; 'terjadi setelah' tidak otomatis berarti 'terjadi karena'"],answer:2,explain:"Kesalahan 'setelah itu, maka karena itu' (post hoc): menganggap urutan waktu sebagai bukti sebab. Perlu pembanding untuk yakin.",hint:"Mungkinkah demam turun tanpa obat juga?"},
{n:63,type:"tf",micro:"Korelasi & sebab",q:"Benar atau Salah: Dua hal yang selalu berubah bersama-sama pasti memiliki hubungan sebab-akibat langsung antara keduanya.",answer:false,explain:"Sebaliknya, mereka bisa punya sebab bersama, hubungannya bisa kebetulan, atau arahnya terbalik. Berubah bersama (korelasi) adalah petunjuk, bukan bukti sebab.",hint:"Berubah bersama ≠ sebab-akibat."},
{n:64,type:"mcq",micro:"Arah terbalik",q:"'Anak yang percaya diri lebih sering angkat tangan di kelas.' Mungkin juga arahnya terbalik, yaitu...",options:["sering angkat tangan & mendapat pengalaman berhasil bisa MEMBANGUN rasa percaya diri","percaya diri membuat anak pintar sehingga ia tahu jawaban & angkat tangan lebih sering","anak yang jarang angkat tangan pasti tidak percaya diri & tidak mungkin berubah menjadi percaya diri"],answer:0,explain:"Kadang yang kita kira 'akibat' justru 'sebab'. Percaya diri bisa menyebabkan angkat tangan, tapi angkat tangan juga bisa menumbuhkan percaya diri.",hint:"Mana sebab, mana akibat — bisa jadi terbalik."},
{n:65,type:"mcq",micro:"Faktor ketiga",q:"'Sekolah dengan lapangan luas punya nilai olahraga lebih tinggi.' Faktor ketiga yang mungkin sebenarnya berperan:",options:["warna lapangan","sekolah dengan dana lebih besar mungkin punya lapangan luas DAN guru olahraga & alat yang lebih baik","jumlah pintu di sekolah"],answer:1,explain:"Faktor tersembunyi (dana) bisa menyebabkan keduanya. Menghubungkan langsung 'lapangan → nilai' melewatkan sebab yang sebenarnya.",hint:"Apa yang bisa menyebabkan lapangan luas SEKALIGUS nilai tinggi?"},
{n:66,type:"open",micro:"Cari penjelasan lain",q:"Klaim: 'Murid yang sarapan bubur mendapat nilai lebih tinggi daripada yang sarapan roti.' Tuliskan dua penjelasan selain 'bubur membuat pintar'.",explain:"Sebelum menerima klaim sebab-akibat, munculkan penjelasan alternatif: sebab bersama, arah terbalik, kebetulan, atau data yang terlalu sedikit.",hint:"Sebab bersama? Kebetulan? Data kurang?",sample:"Penjelasan lain: (1) mungkin keluarga yang menyiapkan bubur hangat setiap pagi juga cenderung lebih teratur mendampingi anak belajar — jadi sebabnya kebiasaan keluarga, bukan buburnya; (2) mungkin jumlah murid yang dibandingkan sedikit sehingga perbedaannya kebetulan & tidak akan muncul lagi pada kelompok yang lebih besar."},
{n:67,type:"mcq",micro:"Kebetulan",q:"Dalam satu kelas 30 anak, dua anak ternyata berulang tahun di tanggal yang sama. Apakah ini butuh 'sebab khusus'?",options:["itu mustahil","ya, pasti ada yang mengaturnya","tidak; dengan cukup banyak orang, kecocokan seperti ini cukup sering terjadi hanya karena peluang"],answer:2,explain:"Beberapa 'kejadian mengejutkan' sebenarnya wajar secara peluang. Tidak semua pola butuh sebab yang disengaja.",hint:"Kadang peluang saja sudah cukup menjelaskan."},
{n:68,type:"mcq",micro:"Sebab yang berkontribusi",q:"Sebuah kecelakaan sepeda terjadi saat: jalan basah, rem agak aus, & pengendara melaju cepat. Cara terbaik memahami sebabnya:",options:["melihat ketiganya sebagai faktor yang berkontribusi; menghilangkan salah satu mungkin sudah cukup mencegah kecelakaan","memilih satu penyebab yang paling mudah dibenahi & menganggap dua lainnya tidak berpengaruh sama sekali","menyalahkan pengendara karena dialah yang terakhir bergerak sebelum kecelakaan itu terjadi pada jalan basah"],answer:0,explain:"Banyak kejadian punya beberapa sebab yang berkontribusi. Pencegahan bisa menyasar faktor mana pun yang paling mudah diubah.",hint:"Beberapa faktor menumpuk, bukan satu."},
{n:69,type:"tf",micro:"Bukti eksperimen",q:"Benar atau Salah: Cara paling kuat untuk memastikan A menyebabkan B adalah dengan sengaja mengubah A sambil menjaga hal lain tetap sama, lalu melihat apakah B berubah.",answer:true,explain:"Percobaan terkontrol memisahkan pengaruh A dari faktor lain. Itu sebabnya sains mengandalkan eksperimen untuk klaim sebab-akibat.",hint:"Ubah satu hal, jaga sisanya."},
{n:70,type:"order",micro:"Menguji klaim sebab-akibat",q:"Urutkan langkah menguji klaim 'musik pelan membuat kelas lebih tenang saat mengerjakan tugas':",items:["Perjelas ukuran 'tenang' (mis. jumlah keributan, jumlah tugas selesai)","Bandingkan hari dengan musik pelan & hari tanpa musik, kondisi lain dibuat serupa","Ulangi beberapa kali agar hasilnya tidak kebetulan","Simpulkan berdasarkan pola, & pertimbangkan penjelasan lain"],answer:[0,1,2,3],explain:"Definisikan ukuran → bandingkan dengan pembanding → ulangi → simpulkan hati-hati.",hint:"Tentukan cara mengukur 'tenang' dulu."},
{n:71,type:"tf",micro:"Cerita yang meyakinkan",q:"Benar atau Salah: Jika sebuah penjelasan sebab-akibat terdengar sangat masuk akal, itu sudah cukup untuk memastikan penjelasan itu benar.",answer:false,explain:"Sebaliknya, otak menyukai cerita yang rapi. Penjelasan yang enak didengar tetap perlu diuji dengan bukti, bukan diterima karena 'terasa benar'.",hint:"Masuk akal ≠ terbukti."},
{n:72,type:"mcq",micro:"Menuduh dari pola",q:"'Setiap kali si A piket, kelas jadi lebih kotor keesokan harinya.' Sebelum menyimpulkan A malas, yang perlu diperiksa:",options:["tidak perlu memeriksa apa-apa","apakah polanya nyata (dicatat berapa kali), & adakah sebab lain (hari itu ada kegiatan yang mengotori kelas, jumlah petugas lebih sedikit)","langsung tegur A"],answer:1,explain:"Pola yang tampak bisa kebetulan atau punya sebab lain. Periksa dulu sebelum menuduh seseorang.",hint:"Polanya nyata? Ada sebab lain?"},
{n:73,type:"mcq",micro:"Sebab besar vs kecil",q:"Sebuah proyek berhasil karena banyak faktor. Menyadari bahwa 'kerja sama tim yang baik' menyumbang jauh lebih besar daripada 'cuaca yang cerah' berarti kamu...",options:["menganggap semua sebab sama pentingnya, sehingga cuaca & kerja sama tim dihitung dengan bobot yang sama persis","mengabaikan sebab yang kecil & hanya fokus pada satu sebab saja agar proyek berikutnya lebih mudah diatur","menimbang bobot tiap sebab, bukan hanya mendaftarnya — berguna untuk memutuskan apa yang perlu dijaga di proyek berikutnya"],answer:2,explain:"Tidak semua sebab sama besar pengaruhnya. Menimbang bobotnya membantu memfokuskan usaha.",hint:"Sebab mana yang paling berpengaruh?"},
{n:74,type:"open",micro:"Saat kamu keliru soal sebab",q:"Ceritakan satu kali kamu yakin sesuatu disebabkan oleh hal tertentu, lalu ternyata sebabnya berbeda. Bagaimana kamu akhirnya tahu?",explain:"Memeriksa langsung sering mengubah dugaan sebab kita. Menebak lalu bertindak berisiko menyalahkan yang salah.",hint:"Dugaan awal + cara kamu akhirnya tahu.",sample:"Aku yakin laptop pinjaman jadi lambat karena adikku menginstal banyak game. Aku sempat kesal padanya. Ternyata setelah dicek, penyimpanannya penuh oleh file video tugas kelompokku sendiri. Aku tahu setelah benar-benar membuka daftar file & melihat ukurannya, bukan hanya menebak."},
{n:75,type:"mcq",micro:"Sebab yang tak bisa diubah vs bisa",q:"Saat mencari solusi, di antara sebab-sebab sebuah masalah, sebaiknya kita fokus pada...",options:["sebab yang berada dalam kendali kita untuk diubah, meski bukan satu-satunya penyebab","menyalahkan keadaan","sebab yang paling tidak mungkin kita ubah"],answer:0,explain:"Memahami semua sebab itu penting, tetapi tindakan paling berguna diarahkan ke sebab yang bisa kita pengaruhi.",hint:"Apa yang bisa KAMU ubah?"},
{n:76,type:"tf",micro:"Tidak ada penjelasan tunggal",q:"Benar atau Salah: Untuk peristiwa sosial yang rumit (mis. mengapa sebuah kegiatan sekolah kurang diminati), cara terbaik adalah menemukan satu penyebab tunggal & berhenti di situ.",answer:false,explain:"Sebaliknya, peristiwa yang melibatkan banyak orang & pilihan jarang punya satu sebab. Penjelasan tunggal biasanya terlalu menyederhanakan.",hint:"Peristiwa rumit = banyak sebab."},
{n:77,type:"mcq",micro:"Bukti yang hilang",q:"Seseorang berkata 'sejak kantin ganti menu, murid jadi lebih sehat'. Yang belum ditunjukkan:",options:["bukti bahwa menu baru enak, & bahwa murid suka makan di kantin lebih sering daripada sebelum menu diganti","bukti bahwa kesehatan murid memang membaik & bahwa perubahannya karena menu, bukan faktor lain (musim, olahraga, dll)","bukti bahwa kantin menaikkan harga, sehingga murid memilih membawa bekal dari rumah dan jadi lebih sehat"],answer:1,explain:"Klaim sebab-akibat perlu menunjukkan bahwa akibatnya nyata & terkait dengan sebab yang disebut, bukan dengan hal lain yang berubah bersamaan.",hint:"Akibatnya nyata? Terkait sebab itu?"},
{n:78,type:"mcq",micro:"Menahan kesimpulan sebab",q:"Kapan sebaiknya kamu berkata 'aku belum tahu pasti apa penyebabnya'?",options:["tidak pernah","setiap kali ada masalah","saat beberapa sebab sama-sama mungkin, belum ada pengujian, & keputusannya berdampak besar pada orang"],answer:2,explain:"Menahan kesimpulan sebab saat bukti belum cukup mencegah solusi yang salah sasaran & tuduhan yang tidak adil.",hint:"Bukti kurang + dampak besar = tahan dulu."},
{n:79,type:"tf",micro:"Sebab & tanggung jawab",q:"Benar atau Salah: Memahami rantai sebab sebuah kesalahan bisa membantu memperbaiki sistem, tanpa berarti tidak ada seorang pun yang bertanggung jawab.",answer:true,explain:"Analisis sebab & tanggung jawab bisa berjalan bersama: kita perbaiki sistemnya DAN orang tetap belajar dari bagiannya.",hint:"Perbaiki sistem + orang tetap belajar."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Sebelum menerima 'A menyebabkan B', tanyakan:",options:["'Apakah A mendahului B? Bisakah ada sebab bersama, arah terbalik, atau kebetulan? Apakah ada pengujian yang mengubah A & melihat B berubah?'","'Apakah A paling sering disebut orang? Apakah B juga terjadi pada orang lain? Apakah ada yang percaya bahwa A menyebabkan B tanpa memeriksanya?'","'Apakah A lebih besar daripada B? Apakah A selalu bersama B? Apakah keduanya cocok bila dihitung dalam jumlah yang sama banyak?'"],answer:0,explain:"Urutan waktu, penjelasan alternatif, & pengujian adalah tiga saringan utama untuk klaim sebab-akibat.",hint:"Urutan? Alternatif? Pengujian?"},
{n:81,type:"mcq",micro:"Analisis banyak sebab",q:"Perpustakaan sekolah makin sepi. Data: jam buka dipangkas, ruang baca dipindah ke lantai atas yang panas, & koleksi baru berkurang. Kesimpulan sebab yang paling matang:",options:["hanya jam buka yang dipangkas, karena itu satu-satunya hal yang bisa dengan mudah diubah oleh pengelola","ketiga faktor kemungkinan berkontribusi; memperbaiki beberapa sekaligus lebih mungkin membalik keadaan daripada satu saja","hanya ruang baca yang panas, karena murid pasti tidak mau membaca di tempat yang tidak nyaman sama sekali"],answer:1,explain:"Penurunan seperti ini biasanya multi-sebab. Solusi yang menyasar beberapa faktor sekaligus lebih kuat.",hint:"Beberapa faktor bekerja bersama."},
{n:82,type:"open",micro:"Analisis sebab lengkap",q:"Pilih satu masalah nyata di kelas atau rumahmu. Tuliskan: (a) akibat/masalah yang terlihat, (b) dua-tiga kemungkinan sebab, (c) cara sederhana menguji sebab mana yang benar, (d) satu tindakan yang menyasar sebab, bukan sekadar akibat.",explain:"Analisis sebab-akibat lengkap bergerak dari gejala ke sebab yang bisa diubah, lalu ke tindakan & pengujian.",hint:"Masalah → sebab → uji → tindakan pada sebab.",sample:"(a) Masalah: meja belajarku selalu berantakan sehingga sulit mulai belajar. (b) Sebab: tidak ada tempat khusus untuk tiap barang; aku menaruh barang sekolah & barang hobi bercampur; aku tidak pernah merapikan setiap hari. (c) Uji: coba seminggu menyediakan kotak terpisah & merapikan 2 menit tiap malam, lihat apakah meja tetap rapi. (d) Tindakan menyasar sebab: buat tempat tetap untuk tiap jenis barang & kebiasaan merapikan singkat setiap malam, bukan sekadar membereskan besar sekali sebulan."},
{n:83,type:"mcq",micro:"Menimbang penjelasan bersaing",q:"Nilai rata-rata kelas turun. Penjelasan A: materi bab ini memang lebih sulit. Penjelasan B: banyak murid sakit saat minggu ujian. Petunjuk: kelas paralel yang materinya sama tapi tidak banyak yang sakit, nilainya stabil. Kesimpulan:",options:["keduanya salah","Penjelasan A lebih kuat","Penjelasan B lebih kuat, karena pembeda antara dua kelas adalah tingkat sakit, bukan materi"],answer:2,explain:"Membandingkan dua kelas yang materinya sama tetapi kondisinya beda memisahkan pengaruh 'sakit' dari 'materi sulit'.",hint:"Apa yang berbeda antara dua kelas?"},
{n:84,type:"tf",micro:"Intervensi di rantai",q:"Benar atau Salah: Dalam rantai sebab-akibat yang panjang, sering ada beberapa titik berbeda di mana kita bisa turun tangan untuk mengubah hasil akhirnya.",answer:true,explain:"Rantai memberi banyak 'titik ungkit'. Memilih titik yang paling mudah & berdampak besar adalah bagian dari solusi yang cerdas.",hint:"Banyak titik untuk memutus rantai."},
{n:85,type:"mcq",micro:"Sebab vs pemicu terakhir",q:"Sebuah pertengkaran pecah saat B menyenggol meja A, tetapi sebelumnya sudah ada minggu-minggu saling sindir. Menyebut 'senggolan meja' sebagai satu-satunya sebab berarti...",options:["melihat pemicu terakhir saja & melewatkan sebab yang menumpuk sebelumnya","menyalahkan A","analisis yang lengkap"],answer:0,explain:"Pemicu terakhir sering hanya 'setetes yang membuat gelas tumpah'. Sebab sebenarnya bisa jauh lebih panjang.",hint:"Pemicu terakhir ≠ seluruh sebab."},
{n:86,type:"order",micro:"Dari masalah ke akar & solusi",q:"Urutkan proses analisis sebab-akibat yang menyeluruh:",items:["Nyatakan akibat/masalah dengan jelas & terukur","Telusuri mundur dengan bertanya 'mengapa' beberapa kali","Daftar semua kemungkinan sebab, termasuk sebab bersama & kebetulan","Kumpulkan bukti atau lakukan pengujian sederhana untuk menyaring sebab","Pilih sebab yang paling didukung & bisa diubah, rancang tindakan","Terapkan, amati apakah akibat berubah, & sesuaikan"],answer:[0,1,2,3,4,5],explain:"Nyatakan masalah → telusuri mundur → daftar sebab → uji → pilih & bertindak → amati & sesuaikan.",hint:"Menyatakan masalah dulu, mengamati hasil terakhir."},
{n:87,type:"mcq",micro:"Umpan balik memperkuat",q:"'Makin sedikit yang datang ke klub, makin membosankan kegiatannya, sehingga makin sedikit lagi yang datang.' Untuk membalik lingkaran ini:",options:["tunggu sampai lebih banyak anggota yang keluar, karena lingkaran itu akan berhenti sendiri pada akhirnya","suntikkan perubahan di satu titik (mis. buat satu kegiatan menarik yang menarik orang kembali) agar putaran berbalik arah","salahkan anggota yang pertama keluar karena dialah yang memulai lingkaran sehingga harus dihukum"],answer:1,explain:"Lingkaran umpan balik bisa berputar ke bawah atau ke atas. Dorongan yang tepat di satu titik bisa membalikkannya.",hint:"Dorong satu titik untuk membalik putaran."},
{n:88,type:"open",micro:"Rancang pengujian sebab",q:"Kamu menduga 'kelas ribut terutama pada jam pelajaran setelah olahraga karena murid masih bersemangat & haus'. Rancang cara menguji dugaan ini secara sederhana & adil.",explain:"Menguji sebab yang melibatkan perilaku berarti membandingkan kondisi & mencoba satu perubahan terarah.",hint:"Bandingkan kondisi + coba satu perubahan.",sample:"Selama dua minggu aku catat tingkat keributan (mis. berapa kali guru menegur) pada jam setelah olahraga & pada jam serupa di hari tanpa olahraga sebelumnya. Aku juga coba satu minggu memberi jeda 5 menit untuk minum & menenangkan diri sebelum pelajaran dimulai, lalu bandingkan. Kalau keributan jelas lebih tinggi setelah olahraga & berkurang saat ada jeda, dugaanku menguat."},
{n:89,type:"mcq",micro:"Sebab yang salah menyalahkan orang",q:"Sebuah alat rusak karena dipakai oleh banyak murid tanpa panduan & tidak pernah dirawat. Menyalahkan hanya murid terakhir yang memakainya...",options:["satu-satunya cara","adil & tepat","melewatkan sebab sistem (tidak ada panduan & perawatan) yang akan membuat alat berikutnya rusak lagi"],answer:2,explain:"Bila sebab akarnya adalah sistem, mengganti 'orang yang disalahkan' tidak mencegah masalah berulang.",hint:"Ganti orang, masalah tetap kembali?"},
{n:90,type:"tf",micro:"Rendah hati soal sebab",q:"Benar atau Salah: Bahkan setelah analisis yang cermat, kita sebaiknya tetap terbuka bahwa pemahaman kita tentang sebab sebuah kejadian bisa diperbaiki oleh bukti baru.",answer:true,explain:"Penalaran sebab-akibat yang matang menghasilkan kesimpulan yang kuat namun bisa direvisi, bukan kepastian yang kaku.",hint:"Kuat, tapi terbuka untuk diperbaiki."},
{n:91,type:"mcq",micro:"Membedakan pola nyata & khayalan",q:"Kamu merasa 'setiap Senin selalu sial'. Cara memeriksanya:",options:["catat kejadian baik & buruk setiap hari selama sebulan, lalu lihat apakah Senin benar-benar berbeda atau kita hanya lebih mengingat yang buruk di hari yang tidak disukai","ingat saja hari-hari Senin yang terasa buruk dan tidak perlu mencatat apa pun, karena ingatan kita sudah cukup akurat untuk menilai pola kejadian sebulan penuh","tanyakan pada beberapa teman apakah Senin mereka juga sial, lalu simpulkan sesuai jawaban mayoritas tanpa mencatat kejadian apa pun milikmu sendiri sama sekali"],answer:0,explain:"Kita cenderung mengingat kejadian yang cocok dengan dugaan (Senin buruk) & melupakan yang tidak. Data harian menguji apakah polanya nyata.",hint:"Catat semua hari, bukan hanya yang diingat."},
{n:92,type:"mcq",micro:"Sebab jangka panjang",q:"Beberapa akibat baru muncul lama setelah sebabnya (mis. kebiasaan belajar di kelas 4 memengaruhi nilai di kelas 6). Ini berarti...",options:["akibat yang lama muncul pasti tidak berhubungan dengan sebabnya, sehingga bisa diabaikan dalam analisis","sebagian hubungan sebab-akibat bekerja perlahan; melewatkannya membuat kita salah menilai apa yang penting hari ini","hanya akibat yang muncul saat itu juga yang pantas dihitung sebagai akibat dari sebuah sebab"],answer:1,explain:"Tidak semua sebab-akibat langsung terlihat. Sebagian keputusan kecil hari ini punya dampak yang menumpuk di kemudian hari.",hint:"Sebagian dampak butuh waktu muncul."},
{n:93,type:"open",micro:"Refleksi",q:"Menurutmu, mengapa orang sering puas dengan penjelasan sebab yang paling sederhana atau paling cepat terpikir, meski belum tentu benar? Bagaimana kamu bisa lebih hati-hati?",explain:"Menyadari kecenderungan berhenti terlalu cepat adalah langkah pertama untuk menelusuri sebab lebih dalam.",hint:"Kenapa berhenti cepat? Cara menahan diri?",sample:"Penjelasan sederhana terasa memuaskan & menghemat tenaga berpikir, apalagi kalau cocok dengan dugaan awal kita. Aku bisa lebih hati-hati dengan sengaja bertanya 'apa penjelasan lain yang mungkin?' & 'bukti apa yang akan menunjukkan penjelasanku salah?' sebelum merasa selesai."},
{n:94,type:"mcq",micro:"Sebab & prediksi kebijakan",q:"Sebelum kelas menerapkan aturan baru untuk mengatasi sebuah masalah, penalaran sebab-akibat menyarankan untuk...",options:["memastikan aturan itu terdengar tegas & mudah diingat, lalu langsung menerapkannya tanpa memperkirakan efek sampingnya","memilih aturan yang disukai paling banyak murid, tanpa memeriksa apakah aturan itu menyasar penyebab masalahnya","memeriksa apakah aturan itu benar-benar menyasar sebab masalah, & memperkirakan akibat sampingannya"],answer:2,explain:"Aturan yang tidak menyasar sebab sebenarnya jarang berhasil, & bisa menimbulkan masalah baru yang tak terduga.",hint:"Menyasar sebab? Efek samping?"},
{n:95,type:"tf",micro:"Tujuan keterampilan ini",q:"Benar atau Salah: Tujuan belajar penalaran sebab-akibat adalah agar kita bisa menjelaskan kejadian secara lebih akurat, memprediksi dengan lebih baik, & memilih tindakan yang benar-benar mengubah hasil.",answer:true,explain:"Sebab-akibat adalah alat berpikir untuk memahami dunia & bertindak di dalamnya dengan lebih efektif — bukan sekadar untuk berdebat.",hint:"Menjelaskan, memprediksi, mengubah hasil."},
{n:96,type:"mcq",micro:"Menilai klaim viral",q:"Postingan viral: 'Kota yang menanam lebih banyak pohon punya angka kejahatan lebih rendah — jadi menanam pohon mengurangi kejahatan.' Sikap kritis:",options:["mungkin ada sebab bersama (kota dengan dana & perhatian lebih pada ruang publik menanam pohon DAN menjaga keamanan); hubungannya menarik tapi belum tentu sebab langsung","pohon langsung mengurangi kejahatan karena penjahat tidak berani beraksi di bawah pohon yang rimbun & teduh, jadi kota sebaiknya menanam pohon di semua jalan secepatnya","kejahatan yang rendah menyebabkan kota menanam pohon, karena kota yang aman pasti lebih senang menanam pohon dibanding kota lain yang sedang dilanda masalah"],answer:0,explain:"Klaim sebab-akibat berbasis 'kota yang X juga Y' sangat rawan faktor ketiga. Menarik untuk diteliti, belum cukup untuk diyakini.",hint:"Faktor ketiga apa yang mungkin berperan?"},
{n:97,type:"mcq",micro:"Kesimpulan terkuat",q:"Masalah: banyak murid tidak mengembalikan alat olahraga. Data: sejak rak alat dipindah ke sudut yang jauh & gelap, tingkat pengembalian turun; kelas yang raknya tetap dekat pintu tidak mengalami penurunan. Kesimpulan paling didukung:",options:["murid sekarang lebih malas","lokasi rak yang jauh & gelap kemungkinan besar menjadi sebab utama turunnya pengembalian","alat olahraga rusak"],answer:1,explain:"Perubahan mulai tepat saat rak dipindah, & kelas pembanding yang raknya tetap tidak terpengaruh — dua petunjuk kuat ke arah 'lokasi rak'.",hint:"Apa yang berubah tepat saat masalah mulai, & apa kata kelas pembanding?"},
{n:98,type:"order",micro:"Menyelidiki sebab kehadiran turun",q:"Kehadiran di kegiatan sore menurun. Urutkan penyelidikan sebab-akibatnya:",items:["Ukur: turun sejak kapan, dari berapa jadi berapa, kelas mana","Daftar kemungkinan sebab (jadwal bentrok, kegiatan berubah, cuaca, transport pulang)","Cari petunjuk pembeda & tanyakan langsung ke murid yang berhenti datang","Uji satu perubahan pada sebab yang paling didukung & pantau kehadiran"],answer:[0,1,2,3],explain:"Ukur → daftar sebab → cari petunjuk & tanya → uji perbaikan.",hint:"Mengukur penurunan lebih dulu."},
{n:99,type:"open",micro:"Panduan pribadi",q:"Tuliskan panduan singkat (3-4 poin) untuk dirimu sendiri sebelum menyimpulkan bahwa satu hal menyebabkan hal lain.",explain:"Panduan ringkas membuat kebiasaan memeriksa klaim sebab-akibat lebih mudah dipakai saat dibutuhkan.",hint:"3-4 poin, dengan katamu sendiri.",sample:"1) Cek urutan waktu: apakah sebab yang kuduga benar-benar terjadi lebih dulu? 2) Pikirkan penjelasan lain: sebab bersama, arah terbalik, atau kebetulan? 3) Cari pembanding: apakah akibatnya tetap muncul tanpa sebab itu? 4) Kalau bisa, uji dengan mengubah satu hal saja. Kalau bukti masih tipis & keputusannya besar, aku tahan dulu kesimpulannya."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti penalaran sebab-akibat yang matang adalah...",options:["menemukan satu sebab yang paling jelas dan paling mudah dilihat, menyalahkannya sepenuhnya, lalu mengambil tindakan secepat mungkin supaya masalah tidak berlarut-larut","mengumpulkan sebanyak mungkin kejadian yang terjadi sebelum sebuah akibat & menganggap semuanya sebagai penyebabnya, lalu menolak semua penjelasan lain yang berbeda","menelusuri rantai sebab, mempertimbangkan banyak faktor & penjelasan alternatif, menguji bila bisa, & mengarahkan tindakan ke sebab yang bisa diubah — sambil tetap terbuka pada bukti baru"],answer:2,explain:"Memahami sebab-akibat dengan baik membuat penjelasan kita lebih akurat, prediksi lebih tepat, & tindakan lebih berdampak.",hint:"Telusuri, timbang, uji, bertindak pada sebab, tetap terbuka."},
];
